
import LAB_POLICY_MANIFEST from './permissions-module.js';
import FUTURE_UI from './future-ui.js';
import { APP_ICON_PNG_B64, APP_ICON_SVG } from './app-icon.js';
const HTML = "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, interactive-widget=resizes-content\">\n<meta name=\"theme-color\" content=\"#070c19\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\"><meta name=\"apple-mobile-web-app-title\" content=\"Wormstar NEO\"><meta name=\"mobile-web-app-capable\" content=\"yes\"><meta name=\"format-detection\" content=\"telephone=no\"><link rel=\"apple-touch-icon\" sizes=\"96x96\" href=\"/apple-touch-icon.png?v=20261025b\"><link rel=\"icon\" type=\"image/svg+xml\" href=\"/icon.svg?v=20261025b\"><link rel=\"manifest\" href=\"/manifest.webmanifest?v=20261025b\"><meta name=\"description\" content=\"Wormstar NEO — Private AI Mission Control, memory, cybersecurity analysis and custom permissions.\">\n<title>Wormstar NEO | Cyber Intelligence Command</title>\n<style>\n:root{color-scheme:dark;font-family:Tahoma,Arial,sans-serif;--bg:#090e17;--surface:#111a27;--line:#293747;--mint:#5ce3c5;--muted:#9aabbd}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#e9f4fa}\n.layout{display:flex;min-height:100vh}\naside{width:248px;flex-shrink:0;border-left:1px solid var(--line);background:#0e1723;padding:26px 16px;display:flex;flex-direction:column}\n.brand{display:flex;align-items:center;gap:12px;direction:ltr;justify-content:flex-end;margin-bottom:36px}\n.logo{font-size:29px;border:1px solid #285b56;background:#153834;border-radius:12px;padding:5px 11px;color:var(--mint)}\n.brand h3{font:bold 20px Arial;margin:0;letter-spacing:1.6px}.brand small{font:10px monospace;color:#79909b}\n.nav{display:grid;gap:7px}.nav button{display:flex;gap:13px;align-items:center;text-align:right;width:100%;background:none;color:#a0aec2;border:1px solid transparent;border-radius:9px;padding:13px 14px}\n.nav button.active{border-color:#2e635d;background:#193735;color:var(--mint)}.nav button:hover{background:#1b2b3b}\n.caption{margin:0 14px 12px;color:#6a7b90;font-size:11px;font-weight:700}\n.sidefooter{margin-top:auto;font-size:12px;line-height:2;color:#8194a9;border:1px solid #233b3f;padding:12px;border-radius:10px}\n.sidefooter a{color:var(--mint);text-decoration:none}\nmain{flex:1;min-width:0}\n.top{border-bottom:1px solid var(--line);padding:20px 32px;display:flex;justify-content:space-between;align-items:center;gap:8px}\n.top small{color:var(--muted)}.live{color:var(--mint);font-size:11px}\n.content{max-width:1100px;margin:auto;padding:40px 32px}\n.eyebrow{font:12px monospace;color:var(--mint);letter-spacing:1.1px}\nh1{font-size:30px;margin:12px 0}p{color:var(--muted);line-height:1.85}\n.header{display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap;margin-bottom:25px}\n.buttons{display:flex;gap:8px;flex-wrap:wrap}\nbutton{font:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}\n.ghost{color:#c2d1dc;background:#162232;border:1px solid #314152;border-radius:8px;padding:9px 13px;font-size:12px}\n.primary{background:var(--mint);color:#062b2b;border:0;border-radius:8px;padding:11px 19px;font-weight:700}\n.panel{border:1px solid var(--line);background:var(--surface);border-radius:16px;overflow:hidden}\n.bar{display:flex;justify-content:space-between;gap:10px;padding:15px 19px;background:#172231;color:#91a5bb;font:11px monospace;border-bottom:1px solid var(--line)}\n.traffic{color:#c2767a;letter-spacing:2px}\n.messages{min-height:320px;max-height:53vh;overflow-y:auto;padding:25px 22px}\n.welcome{text-align:center;max-width:620px;margin:55px auto}.welcome .symbol{font-size:40px;color:var(--mint)}\n.prompts{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:30px}\n.prompts button{background:#172638;text-align:right;color:#c9d7e2;border:1px solid #334356;border-radius:10px;padding:18px;min-height:72px;font-size:12px}\n.prompts button:hover{border-color:#3a9d88}\n.message{margin-bottom:23px;max-width:800px}\n.message .who{font-size:11px;color:var(--mint);font-weight:700;margin-bottom:8px}\n.bubble{padding:14px 16px;border:1px solid #334558;background:#142233;border-radius:11px;font-size:13px;white-space:pre-wrap;line-height:1.95;overflow-wrap:anywhere}\n.message.ai .bubble{border-color:#21534f;background:#102927}\n.compose{border-top:1px solid var(--line);padding:16px}\ntextarea{width:100%;border:1px solid #334357;border-radius:10px;background:#0e1a29;color:#edf7f8;resize:vertical;padding:16px;min-height:112px;outline:none;font:13px Tahoma,Arial;line-height:1.8}\ntextarea:focus{border-color:#59c4af}\n.composefoot{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:10px;flex-wrap:wrap;font-size:10px;color:#8295a9}\n#indicators{font:11px monospace;color:var(--mint);overflow-wrap:anywhere;margin-bottom:9px}\n.status{margin-top:9px;color:#ffbdb1;font-size:12px}\n#auth{background:#101c29;border:1px solid #30564f;border-radius:18px;max-width:500px;padding:32px;margin:70px auto;text-align:center}\n#auth .symbol{font-size:50px;color:var(--mint)}\n#auth input{background:#0b1825;border:1px solid #3a5a62;color:white;border-radius:8px;padding:13px;width:100%;margin:12px 0;font:14px monospace}\n#auth button{width:100%}\n#lab{display:none}.hidden{display:none!important}\n@media(max-width:750px){.layout{display:block}aside{width:100%;padding:12px;display:block}.brand{margin-bottom:12px}.caption,.sidefooter{display:none}.nav{display:flex;overflow:auto;gap:5px}.nav button{width:auto;white-space:nowrap;font-size:11px;padding:9px}.top{padding:15px}.content{padding:25px 12px}h1{font-size:24px}.prompts{grid-template-columns:1fr}.welcome{margin:22px auto}.messages{max-height:48vh}}\n\n.ws-studio-entry{width:100%;background:#172f33;border:1px solid #245c58;color:#64e4cf;border-radius:10px;padding:12px;margin:12px 0;text-align:right;font-weight:700}\n.ws-studio-entry:hover,.ws-studio-entry.active{background:#245044}\n.ws-studio-head{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;align-items:center}\n.ws-studio-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;margin:22px 0}\n.ws-studio-card{background:#111d2b;border:1px solid #2a4050;border-radius:14px;padding:19px;min-width:0}\n.ws-studio-card h2{margin:0 0 10px;font-size:19px}\n.ws-studio-card p{font-size:12px;margin:0 0 15px}\n.ws-field-label{display:block;font-size:12px;font-weight:700;color:#b8cbd4;margin:12px 0 7px}\n.ws-studio-card input[type=text],.ws-studio-card textarea,.ws-studio-card input[type=search]{width:100%;background:#0c1724;color:#ebf6fc;border:1px solid #30495c;border-radius:9px;padding:11px;font:13px Tahoma,Arial;outline:none}\n.ws-studio-card textarea{min-height:125px;resize:vertical}\n.ws-studio-card input[type=file]{width:100%;font-size:11px;overflow:hidden;color:#9bb4c1;padding:12px 0}\n.ws-note-row{display:flex;justify-content:space-between;align-items:center;gap:10px;border:1px solid #2d4355;border-radius:9px;padding:11px;margin:8px 0}\n.ws-note-row strong{font-size:12px;display:block;overflow-wrap:anywhere}\n.ws-note-row small{font-size:10px;color:#849cab}\n.ws-note-actions{display:flex;gap:5px;flex-shrink:0}\n.ws-note-actions button{background:#1b2f3d;color:#bfe1e6;border:1px solid #3b5564;border-radius:6px;padding:7px 9px;font-size:11px}\n.ws-note-actions button:hover{background:#24564e}\n.ws-help{color:#7994a3;font-size:11px;line-height:1.7}\n.ws-studio-notice{margin-top:12px;color:#68e4cb;font-size:12px;white-space:pre-wrap}\n.ws-knowledge-list{max-height:410px;overflow:auto}\n.ws-wide{grid-column:1/-1}\n.ws-counters{font-size:12px;color:#92a8b7}\n.ws-text-preview{font-size:11px;white-space:pre-wrap;color:#aebdc9;background:#0c1724;border:1px solid #304458;padding:12px;border-radius:8px;max-height:130px;overflow:auto}\n.ws-disclaimer{font-size:11px;color:#8d9cab;margin-top:11px}\n@media(max-width:800px){.ws-studio-grid{grid-template-columns:1fr}.ws-studio-card{padding:14px}}\n\n#studio select{background:#0e1a29;color:#eef9fb;border:1px solid #3a4b5e;border-radius:8px;width:100%;padding:12px;margin:8px 0 16px;font:13px Tahoma,Arial}.ws-ai-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:9px}.ws-ai-actions .ghost{font-size:11px;padding:7px 10px}.ws-memory-sources{font-size:11px;color:#55d9c2;margin-top:7px}\n\n#sbPanel input[type=email],#sbPanel input[type=password]{width:100%;padding:12px;background:#0c1724;color:#edf7fc;border:1px solid #30495c;border-radius:9px;font:13px Tahoma,Arial;margin:6px 0 15px}\n#sbPanel .buttons{margin:14px 0}.ws-studio-notice{white-space:pre-wrap;line-height:1.8}\n#researchUrl{width:100%;background:#0c1724;color:#ebf6fc;border:1px solid #30495c;border-radius:9px;padding:11px;font:13px Tahoma,Arial;margin:5px 0 12px}\n\n#policyControlPanel{border-color:#346358;background:#122524}\n#policyControlPanel .ws-policy-modes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0}\n#policyControlPanel .ws-policy-modes label,#policyControlPanel .ws-policy-switches label{display:flex;gap:8px;align-items:center;font-size:12px;color:#c9dfdf;line-height:1.6}\n#policyControlPanel input[type=checkbox]{accent-color:#5ce3c5;width:16px;height:16px;flex:0 0 16px}\n#policyControlPanel .ws-policy-switches{display:flex;flex-direction:column;gap:10px;margin:15px 0 20px}\n#policyControlPanel input[type=number],#policyControlPanel input[type=text],#policyControlPanel select{background:#0c1724;border:1px solid #30495c;color:white;border-radius:8px;padding:11px;width:100%;font:13px Tahoma,Arial}\n#policyControlPanel textarea{min-height:80px}\n#policyControlPanel .ws-policy-test{margin-top:24px;padding:16px;border-radius:10px;border:1px dashed #346358;display:flex;flex-direction:column;gap:10px}\n#policyControlPanel .ws-policy-test h3{font-size:15px;margin:0 0 4px}\n@media(max-width:650px){#policyControlPanel .ws-policy-modes{grid-template-columns:1fr}}\n</style>\n</head><body>\n<div class=\"layout\">\n<aside>\n <div class=\"brand\"><div><h3>WORMSTAR</h3><small>NEO · MISSION CONTROL</small></div><div class=\"logo\">⌘</div></div>\n <p class=\"caption\">منظومة الذكاء المخصص</p>\n <nav class=\"nav\" id=\"nav\">\n  <button class=\"active\" data-mode=\"assistant\">◈ المساعد الذكي</button>\n  <button data-mode=\"code\">⌘ مراجعة الأكواد</button>\n  <button data-mode=\"logs\">▤ تحليل السجلات</button>\n  <button data-mode=\"ioc\">◎ مؤشرات الاختراق</button>\n  <button data-mode=\"ctf\">⚑ مختبر CTF</button>\n  <button data-mode=\"report\">▣ التقارير</button>\n </nav>\n <button type=\"button\" class=\"ws-studio-entry\" id=\"studioTab\">⚙ استوديو تخصيص الذكاء وذاكرته</button>\n <div class=\"sidefooter\">Cloudflare Workers + Workers AI<br><a href=\"https://github.com/abdulstarzeki001-sketch/Wormstar\" target=\"_blank\" rel=\"noopener\">المستودع الأصلي ↗</a></div>\n</aside>\n<main>\n <div class=\"top\"><strong>Wormstar AI Lab</strong><span class=\"live\">● CLOUD WORKER ONLINE</span><button class=\"ghost\" id=\"logout\" style=\"display:none\">تسجيل الخروج</button></div>\n <div class=\"content\">\n  <section id=\"auth\" class=\"ws-gateway\" aria-labelledby=\"gateHeadline\">\n  <div class=\"ws-gate-line\"><div class=\"ws-gate-wordmark\"><span class=\"ws-gate-monogram\">W</span><span><b>WORMSTAR</b><small>NEO / MISSION CONTROL</small></span></div><div class=\"ws-gate-connected\"><span class=\"ws-gate-beacon\"></span> CLOUDFLARE EDGE · ONLINE</div></div>\n  <div class=\"ws-gate-grid\">\n   <div class=\"ws-gate-hero\">\n    <div class=\"ws-gate-overline\"><span>◈</span> PRIVATE CYBER INTELLIGENCE // 2026</div>\n    <h1 id=\"gateHeadline\">الجيل القادم<br>من <em>التحكم بالذكاء.</em></h1>\n    <p>منظومة واحدة لإدارة ذكائك الخاص. برمج شخصيته، قيّد صلاحياته، واربط معرفته بذاكرة دائمة. كل شيء تحت سيطرتك.</p>\n    <div class=\"ws-gate-featureline\"><span><i>01</i> INTELLIGENCE</span><span><i>02</i> MEMORY</span><span><i>03</i> DEFENSE</span></div>\n    <div class=\"ws-gate-emblem-wrap\" aria-hidden=\"true\"><span class=\"ws-gate-ring outer\"></span><span class=\"ws-gate-ring inner\"></span><div class=\"ws-gate-emblem\"><img src=\"/icon.svg?v=20261025b\" alt=\"\"></div><span class=\"ws-gate-label one\">SYSTEM / READY</span><span class=\"ws-gate-label two\">ZERO-TRUST ARCHITECTURE</span></div>\n   </div>\n   <div class=\"ws-gate-access\">\n    <div class=\"ws-gate-cardcap\"><span>◆ VAULT ACCESS</span><span class=\"ws-gate-tiny-led\"></span></div>\n    <div class=\"ws-gate-appicon\"><img src=\"/apple-touch-icon.png?v=20261025b\" alt=\"درع Wormstar NEO\"></div>\n    <div class=\"ws-gate-caption\">PRIVATE ACCESS / LEVEL 01</div>\n    <h2>بوابة WORMSTAR NEO</h2>\n    <p>ادخل إلى منصتك السحابية الخاصة. جميع العمليات الحساسة تتحقق من صلاحياتك على الخادم.</p>\n    <form id=\"loginForm\" autocomplete=\"off\">\n     <label for=\"token\">مفتاح الدخول إلى المختبر</label>\n     <div class=\"ws-gate-input-wrap\"><span>◈</span><input type=\"password\" id=\"token\" placeholder=\"أدخل مفتاح الوصول الخاص\" autocomplete=\"current-password\" required></div>\n     <button class=\"primary ws-gate-submit\" type=\"submit\"><span>دخول إلى غرفة العمليات</span><span>↗</span></button>\n    </form>\n    <div class=\"status\" id=\"authStatus\" role=\"status\" aria-live=\"polite\"></div>\n    <div class=\"ws-gate-secure\"><span>◉ AUTHENTICATED SESSION</span><span>256 / SECURE EDGE</span></div>\n   </div>\n  </div>\n  <div class=\"ws-gate-bottom\"><span>WORMSTAR INTELLIGENCE DIVISION · V3</span><span>AUTHORIZED ACCESS ONLY</span></div>\n </section>\n <section id=\"lab\">\n   <div class=\"header\"><div><div class=\"eyebrow\">AI SECURITY WORKSPACE / <span id=\"modeKey\">ASSISTANT</span></div>\n    <h1 id=\"modeTitle\">المساعد الذكي</h1><p id=\"modeDesc\">مساعد لتحليل الأمن السيبراني ضمن اختبارات مصرح بها.</p></div>\n    <div class=\"buttons\"><button class=\"ghost\" id=\"policyDetails\">سياسة المختبر</button><button class=\"ghost\" id=\"clear\">جلسة جديدة</button><button class=\"ghost\" id=\"export\">تصدير Markdown</button></div>\n   </div>\n   <div class=\"ws-disclaimer\" id=\"policyBanner\" aria-live=\"polite\">سياسة المختبر مفعّلة على الخادم. التعليمات التي تحفظها في الذاكرة لا تمنح صلاحيات جديدة.</div>\n   <section class=\"panel\">\n    <div class=\"bar\"><span>● ● ●</span><span>WORMSTAR / <span id=\"consoleMode\">assistant</span></span><span>Private session</span></div>\n    <div id=\"messages\" class=\"messages\"></div>\n    <div class=\"compose\">\n      <div id=\"indicators\"></div>\n      <form id=\"form\"><textarea maxlength=\"12000\" id=\"prompt\" placeholder=\"اكتب سؤالك أو ألصق النص المراد تحليله...\" required></textarea>\n        <div class=\"composefoot\"><span>تحليل نصي · لا ينفذ أوامر على نظام التشغيل · <span id=\"counter\">0</span>/12000</span><button class=\"primary\" id=\"submit\">إرسال للتحليل ◀</button></div>\n      </form><div class=\"status\" id=\"status\"></div>\n    </div>\n   </section>\n  </section>\n\n  <section id=\"studio\" style=\"display:none\">\n    <div class=\"ws-studio-head\"><div><div class=\"eyebrow\">WORMSTAR / CUSTOM AI STUDIO</div><h1>مركز التحكم بذكائك وذاكرته</h1><p>خصص سلوك المساعد، امنحه ملفات معرفة، واحتفظ بالتصحيحات كي يستخدمها في الجلسات التالية.</p></div>\n      <div class=\"buttons\"><button type=\"button\" class=\"ghost\" id=\"studioRefresh\">تحديث الذاكرة</button><button type=\"button\" class=\"ghost\" id=\"studioExport\">نسخة احتياطية JSON</button><button type=\"button\" class=\"primary\" id=\"backToChat\">العودة إلى المحادثة ←</button></div>\n    </div>\n    <div class=\"ws-studio-grid\">\n\n      <div class=\"ws-studio-card ws-wide\" id=\"policyControlPanel\">\n        <div class=\"eyebrow\">WORMSTAR / OWNER ENFORCED POLICY</div>\n        <h2>⚙ اتجاه الذكاء والصلاحيات التشغيلية</h2>\n        <p>اكتب مهمتك الأساسية وحدد ما يسمح خادم Cloudflare بتنفيذه. الأنماط والحدود والوظائف المحددة تفرضها API على الخادم.</p>\n        <label class=\"ws-field-label\" for=\"pMission\">الاتجاه الخاص / المهمة الأساسية</label>\n        <textarea id=\"pMission\" maxlength=\"2000\" placeholder=\"مثلاً: راجع فقط مشاريع Python التعليمية التي أرفعها، وقدّم تقريراً واضحاً...\"></textarea>\n        <label class=\"ws-field-label\" for=\"pStyle\">أسلوب الإجابة المطلوب</label><input type=\"text\" id=\"pStyle\" maxlength=\"140\" placeholder=\"واضح ودقيق\">\n        <label class=\"ws-field-label\">أنماط التحليل المسموحة (البقية سيرفضها الخادم)</label>\n        <div class=\"ws-policy-modes\">\n         <label><input type=\"checkbox\" data-policy-mode=\"assistant\"> مساعد عام</label>\n         <label><input type=\"checkbox\" data-policy-mode=\"code\"> الأكواد</label>\n         <label><input type=\"checkbox\" data-policy-mode=\"logs\"> السجلات</label>\n         <label><input type=\"checkbox\" data-policy-mode=\"ioc\"> المؤشرات</label>\n         <label><input type=\"checkbox\" data-policy-mode=\"ctf\"> CTF</label>\n         <label><input type=\"checkbox\" data-policy-mode=\"report\"> التقارير</label>\n        </div>\n        <label class=\"ws-field-label\" for=\"pRequired\">عبارات إلزامية (واحدة بكل سطر؛ يكفي ظهور واحدة في السؤال)</label>\n        <textarea id=\"pRequired\" placeholder=\"اسم المشروع&#10;مصطلح النطاق\"></textarea>\n        <div class=\"ws-policy-modes\">\n         <div><label class=\"ws-field-label\" for=\"pMaxInput\">الحد الأقصى لحروف الطلب</label><input type=\"number\" id=\"pMaxInput\" min=\"200\" max=\"12000\" step=\"100\"></div>\n         <div><label class=\"ws-field-label\" for=\"pMaxTokens\">الحد الأقصى لرموز الإجابة</label><input type=\"number\" id=\"pMaxTokens\" min=\"128\" max=\"1800\" step=\"1\"></div>\n        </div>\n        <label class=\"ws-field-label\" for=\"pWorkflow\">خطوات العمل (سطر لكل خطوة، بحد أقصى 8)</label><textarea id=\"pWorkflow\"></textarea>\n        <div class=\"ws-policy-switches\">\n         <label><input type=\"checkbox\" id=\"pMemory\"> الرجوع إلى الذاكرة في الإجابات</label>\n         <label><input type=\"checkbox\" id=\"pWeb\"> السماح باستيراد الويب (Firecrawl)</label>\n         <label><input type=\"checkbox\" id=\"pDelete\"> السماح بحذف المراجع</label>\n        </div>\n        <div class=\"buttons\"><button type=\"button\" class=\"primary\" id=\"pSave\">حفظ قيود التشغيل</button><button type=\"button\" class=\"ghost\" id=\"pReload\">إعادة تحميل السياسة</button></div>\n        <div class=\"ws-studio-notice\" id=\"pStatus\" role=\"status\"></div>\n        <div class=\"ws-policy-test\">\n         <h3>اختبر القيود قبل حفظها</h3>\n         <select id=\"pTestMode\" aria-label=\"الوضع التجريبي\"><option value=\"assistant\">المساعد</option><option value=\"code\">الأكواد</option><option value=\"logs\">السجلات</option><option value=\"ioc\">المؤشرات</option><option value=\"ctf\">CTF</option><option value=\"report\">التقارير</option></select>\n         <input type=\"text\" id=\"pTestInput\" maxlength=\"12000\" placeholder=\"اكتب طلباً لتجربة القواعد\">\n         <button type=\"button\" class=\"ghost\" id=\"pTest\">اختبار سياسة الاتجاه</button>\n         <div id=\"pTestResult\" class=\"ws-studio-notice\" role=\"status\"></div>\n        </div>\n        <p class=\"ws-disclaimer\">الأنماط، حجم الإدخال، العبارات، وتفعيل الأدوات تُفرض برمجياً. أما الأسلوب والمهمة وخطوات التفكير فهي تعليمات للنموذج وليست ضماناً دلالياً مطلقاً.</p>\n      </div>\n      <div class=\"ws-studio-card\"><h2>⚙ شخصية الذكاء وتعليماته</h2><p>هذه التعليمات تُحفظ في قاعدة البيانات وتطبّق على الأسئلة التالية.</p>\n        <label class=\"ws-field-label\" for=\"aiName\">اسم المساعد</label><input id=\"aiName\" type=\"text\" maxlength=\"90\" placeholder=\"Wormstar\">\n        <label class=\"ws-field-label\" for=\"aiInstructions\">أوامرك الخاصة: الدور، الأسلوب، الأولويات</label><textarea id=\"aiInstructions\" maxlength=\"11000\" placeholder=\"مثلاً: حلل الأكواد خطوة بخطوة، ثم اقترح اختبارات وحدات...\"></textarea>\n        <label class=\"ws-field-label\" for=\"aiLimits\">قيودك المخصصة على العمل</label><textarea id=\"aiLimits\" maxlength=\"6000\" placeholder=\"مثلاً: لا تفترض وجود صلاحيات، اكتب كل نتيجة بالعربية...\"></textarea>\n        <button class=\"primary\" type=\"button\" id=\"saveProfile\">حفظ الشخصية والتعليمات</button><div class=\"ws-studio-notice\" id=\"profileStatus\"></div>\n      </div>\n      <div class=\"ws-studio-card\"><h2>＋ إضافة معرفة دائمة</h2><p>ارفع كوداً أو نصاً، أو اكتب معلومة تريد استرجاعها لاحقاً. الملفات تظل مراجع ولا يتم تنفيذها.</p>\n        <label class=\"ws-field-label\" for=\"noteTitle\">عنوان المرجع</label><input id=\"noteTitle\" type=\"text\" maxlength=\"130\" placeholder=\"مثلاً: طريقة العمل في مشروعي\">\n        <label class=\"ws-field-label\" for=\"noteTemplate\">قالب معرفة جاهز (اختياري)</label><select id=\"noteTemplate\"><option value=\"\">ابدأ من الصفر أو اختر قالباً احترافياً</option><option value=\"architecture\">مواصفات مشروع وبرمجة</option><option value=\"security\">تقييم أمني دفاعي</option><option value=\"correction\">تصحيح تعليم الذكاء</option><option value=\"incident\">تقرير حادث وسجلات</option></select><label class=\"ws-field-label\" for=\"noteKind\">نوع المعرفة</label><select id=\"noteKind\"><option value=\"note\">ملاحظة / مرجع</option><option value=\"correction\">تصحيح يوجّه الإجابات القادمة</option></select>\n        <label class=\"ws-field-label\" for=\"noteBody\">ملاحظة أو كود أو تصحيح</label><textarea id=\"noteBody\" maxlength=\"60000\" placeholder=\"ألصق كوداً، مواصفات مشروع، مثالاً برمجياً، أو تصحيحاً...\"></textarea>\n        <button class=\"primary\" type=\"button\" id=\"saveNote\">إضافة إلى الذاكرة</button>\n        <label class=\"ws-field-label\" for=\"uploadFiles\">إضافة ملفات نصية وأكواد</label>\n        <input type=\"file\" id=\"uploadFiles\" multiple accept=\".txt,.md,.py,.js,.jsx,.ts,.tsx,.json,.jsonl,.html,.css,.sql,.yaml,.yml,.xml,.csv,.sh,.java,.go,.rs,.c,.cpp,.h,.kt,.swift,.log,.toml,.ini\">\n        <p class=\"ws-help\">الحد لكل ملف: 80 كيلوبايت. ملفات PDF وZIP والملفات الثنائية غير مدعومة بهذه النسخة.</p>\n        <button class=\"ghost\" type=\"button\" id=\"importFiles\">حفظ الملفات المختارة</button>\n        <label class=\"ws-field-label\" for=\"researchUrl\">جلب وثائق أو صفحة ويب بواسطة Firecrawl</label>\n        <input type=\"url\" id=\"researchUrl\" placeholder=\"https://docs.example.com/article\" maxlength=\"2048\">\n        <button class=\"ghost\" type=\"button\" id=\"importResearch\">استيراد الصفحة إلى الذاكرة</button>\n        <p class=\"ws-help\">يتطلب تفعيل Firecrawl إعداد السر FIRECRAWL_API_KEY على خادم Cloudflare. يستخدم فقط عند الضغط على استيراد.</p>\n        <div class=\"ws-studio-notice\" id=\"knowledgeStatus\"></div>\n      </div>\n      <div class=\"ws-studio-card ws-wide\"><div class=\"ws-studio-head\"><div><h2>▤ مكتبة الذاكرة</h2><p>يمكنك فتح كل مرجع وتحريره أو حذفه. ويبحث المساعد في المراجع المحفوظة عند كل سؤال.</p></div><span class=\"ws-counters\" id=\"memoryCount\">0 مرجع</span></div>\n        <div class=\"ws-library-filters\" role=\"group\" aria-label=\"تصفية مكتبة الذاكرة\"><button type=\"button\" class=\"active\" data-library-kind=\"all\">الكل</button><button type=\"button\" data-library-kind=\"file\">ملفات وأكواد</button><button type=\"button\" data-library-kind=\"note\">المراجع</button><button type=\"button\" data-library-kind=\"correction\">التصحيحات</button></div><input type=\"search\" id=\"memorySearch\" placeholder=\"ابحث في العناوين والمقتطفات...\" aria-label=\"البحث في الذاكرة\"><div id=\"libraryVisibleCount\" class=\"ws-library-visible\" aria-live=\"polite\"></div>\n        <div class=\"ws-knowledge-list\" id=\"memoryList\"></div>\n        <div id=\"memoryEditor\" class=\"hidden\">\n          <label class=\"ws-field-label\" for=\"editTitle\">عنوان المرجع</label><input type=\"text\" id=\"editTitle\" maxlength=\"130\">\n          <label class=\"ws-field-label\" for=\"editContent\">النص المحفوظ</label><textarea id=\"editContent\" maxlength=\"60000\"></textarea>\n          <div class=\"buttons\"><button type=\"button\" class=\"primary\" id=\"updateMemory\">حفظ التعديل</button><button type=\"button\" class=\"ghost\" id=\"cancelMemory\">إغلاق التحرير</button></div>\n        </div>\n        <p class=\"ws-disclaimer\">الذاكرة تقوّي الإجابات بالرجوع لملفاتك وتصحيحاتك، لكنها لا تعيد تدريب أوزان النموذج ولا تعدّل شيفرة Worker تلقائياً.</p>\n      </div>\n      <div class=\"ws-studio-card ws-wide\" id=\"sbPanel\">\n <div class=\"sb-hero\"><div><div class=\"eyebrow\">WORMSTAR / CLOUD VAULT / SUPABASE</div><h2>مركز الذاكرة السحابية</h2>\n <p>نسخ هوية الذكاء وقيوده وملفاته وتصحيحاته، واستعادتها من حسابك بأمان.</p>\n <div class=\"sb-hero-tags\"><span>◆ OWNER ACCESS</span><span>◎ RLS SECURITY</span><span>⬡ D1 ↔ SUPABASE</span></div></div>\n <div class=\"sb-connection-indicator\"><span class=\"sb-connection-emblem\">⬡</span><strong id=\"sbCloudBadge\">غير متصل</strong><small id=\"sbLastChecked\">يلزم ربط حسابك</small></div></div>\n <div class=\"sb-system-metrics\" aria-label=\"ملخص الذاكرة السحابية\">\n <div class=\"sb-stat\"><span>▤ المعرفة المحفوظة</span><strong id=\"sbCloudItems\">—</strong><small>المراجع والأكواد</small></div>\n <div class=\"sb-stat\"><span>✦ سجل التدريب</span><strong id=\"sbCloudTraining\">—</strong><small>التصحيحات والدروس</small></div>\n <div class=\"sb-stat\"><span>⌁ الإصدارات السابقة</span><strong id=\"sbCloudVersions\">—</strong><small>تاريخ تعديل الملفات</small></div>\n <div class=\"sb-stat\"><span>⛨ الهوية والصلاحيات</span><strong id=\"sbCloudProfileState\">—</strong><small>نُسخ إعداداتك (من 2)</small></div></div>\n <div class=\"sb-security-note\"><span>⛨</span><div><b>مساحة خاصة بحسابك</b><p>تفصل قواعد Supabase بيانات المستخدمين بواسطة Row Level Security. مفاتيح الإدارة السرية لا تُستخدم في المتصفح.</p></div></div>\n <div id=\"sbSignedOut\" class=\"sb-connect-zone\"><div class=\"sb-zone-title\"><div><div class=\"eyebrow\">01 / SECURE CONNECTION</div><h3>ربط حساب الذاكرة</h3><p>سجّل الدخول بحساب مستخدم Supabase Auth، وليس بالضرورة حساب لوحة إدارة Supabase.</p></div><span class=\"sb-zone-icon\">◈</span></div>\n <div class=\"sb-form-grid\"><div><label class=\"ws-field-label\" for=\"sbEmail\">البريد الإلكتروني</label><input id=\"sbEmail\" type=\"email\" inputmode=\"email\" autocapitalize=\"none\" autocomplete=\"username\" placeholder=\"you@example.com\"></div>\n <div><label class=\"ws-field-label\" for=\"sbPassword\">كلمة المرور</label><input id=\"sbPassword\" type=\"password\" autocomplete=\"current-password\" placeholder=\"كلمة مرور الحساب\"></div></div>\n <div class=\"sb-actions\"><button type=\"button\" class=\"primary\" id=\"sbLogin\">ربط Supabase بأمان ↗</button><button type=\"button\" class=\"ghost\" id=\"sbSignUp\">إنشاء حساب</button><button type=\"button\" class=\"ghost\" id=\"sbResetPassword\">نسيت كلمة المرور؟</button></div>\n <label class=\"sb-remember-option\" for=\"sbRemember\"><input type=\"checkbox\" id=\"sbRemember\" checked><span><strong>إبقاء Supabase متصلاً على هذا الجهاز</strong><small>سيحفظ التطبيق رمز تجديد الجلسة في هذا المتصفح ويعيد التحقق منه عند التشغيل. لا يعمل على الأجهزة الأخرى؛ عطّل الخيار على الأجهزة المشتركة.</small></span></label><p class=\"sb-form-footnote\">يمكن إنشاء حساب مستقل للنسخ الاحتياطي (بكلمة مرور لا تقل عن 8 أحرف). قد يلزم تأكيد البريد الإلكتروني. تأكّد من اختيار الحساب الصحيح: أول حساب موثّق يرتبط بذاكرة Wormstar ويُمنع تبديله تلقائياً.</p></div>\n <div id=\"sbSignedIn\" class=\"sb-connect-zone hidden\"><div class=\"sb-zone-title\"><div><div class=\"eyebrow\">02 / SECURED SESSION</div><h3>مخزن Supabase متصل</h3><p><strong id=\"sbCurrentUser\"></strong><small class=\"sb-owner-lock\" id=\"sbOwnerLockStatus\">الذاكرة مرتبطة بحساب Supabase موثّق واحد فقط.</small></p></div><button type=\"button\" class=\"ghost sb-logout\" id=\"sbLogout\">فصل الحساب</button></div>\n <div class=\"sb-action-cards\">\n <div class=\"sb-action-card sb-primary-action\"><span>01 / BACKUP</span><h4>حفظ نسخة جديدة</h4><p>انسخ تعليماتك والسياسة والمراجع من D1 إلى حسابك السحابي.</p><button type=\"button\" class=\"primary\" id=\"sbBackupNow\">نسخ الذاكرة الآن ↗</button></div>\n <div class=\"sb-action-card\"><span>02 / RESTORE</span><h4>استرجاع المعرفة</h4><p>أعد المراجع غير الموجودة، بعد تأكيدك، دون حذف الموجودة.</p><button type=\"button\" class=\"ghost\" id=\"sbRestoreNow\">استعادة الملفات ↗</button></div>\n <div class=\"sb-action-card\"><span>03 / POLICY</span><h4>استرجاع قيود الذكاء</h4><p>استعد سياسة التشغيل المحفوظة بعد الموافقة.</p><button type=\"button\" class=\"ghost\" id=\"sbRestorePolicy\">استعادة السياسة ↗</button></div>\n </div><div class=\"sb-library-import\"><div><span class=\"eyebrow\">KNOWLEDGE LIBRARY / 25 GUIDES</span><h4>مكتبة Wormstar التأسيسية على Supabase</h4><p>استيراد المراجع الناقصة فقط إلى Cloudflare D1، مع الاحتفاظ بملفاتك الحالية.</p></div><button type=\"button\" class=\"ghost\" id=\"sbImportStarter\">استيراد المراجع الناقصة ↗</button></div><div class=\"sb-secondary-actions\"><button type=\"button\" class=\"ghost\" id=\"sbRefreshStats\">↻ تحديث الحالة</button><span>التعديلات الجديدة تتم محاولة مزامنتها خلال الجلسة المتصلة؛ النسخ اليدوي أوضح وسيلة للتأكد من الحفظ.</span></div></div>\n <div class=\"ws-studio-notice sb-message\" id=\"sbStatus\" role=\"status\" aria-live=\"polite\"></div>\n <section class=\"sb-timeline\" aria-label=\"آخر عمليات المزامنة\"><div class=\"sb-timeline-header\"><div><div class=\"eyebrow\">SYNC / AUDIT TRAIL</div><h3>سجل العمليات السحابية</h3></div><small id=\"sbHistoryLabel\">لم يرتبط أي حساب بعد</small></div>\n <div id=\"sbHistory\" class=\"sb-timeline-list\"><p>سجّل الدخول لعرض عمليات النسخ والاستعادة.</p></div></section>\n <p class=\"ws-disclaimer sb-privacy-footer\">Cloudflare D1 يبقى مصدر الذاكرة أثناء تشغيل الذكاء، وSupabase يحتفظ بنسخة خاصة بحساب موثّق واحد. استمرار الاتصال يعتمد على صلاحية جلسة Supabase وبيانات المتصفح؛ وقد تحتاج لإعادة الدخول إذا انتهت الجلسة أو حُذفت بيانات Safari. هذا حفظ واسترجاع للمعلومات وليس تدريباً مباشراً لأوزان النموذج.</p>\n</div>\n    </div>\n  </section>\n\n </div>\n</main></div>\n<script>\n(function(){\n'use strict';\nconst titles={\n assistant:['المساعد الذكي','استفسارات أمنية، تخطيط اختبار مصرح به، وإرشاد تقني'],\n code:['مراجعة الأكواد','تدقيق المقاطع البرمجية وشرح الثغرات والإصلاحات'],\n logs:['تحليل السجلات','تحليل الأحداث وإنشاء خط زمني لحادث أمني'],\n ioc:['مؤشرات الاختراق','تصنيف عناوين الشبكة والروابط وبصمات الملفات محلياً'],\n ctf:['مختبر CTF','تعليم وتقنيات حل تحديات المختبرات التدريبية'],\n report:['التقارير','صياغة تقارير الثغرات والاستجابة للحوادث']\n};\nconst examples={\n assistant:['اشرح الفرق بين SAST و DAST','أنشئ خطة اختبار مصرح به لتطبيق ويب','أعد نموذج تهديدات لخدمة SaaS'],\n code:['حلّل الكود المرفق بحثاً عن SQL injection','راجع طريقة التحقق من المدخلات','اقترح اختبار وحدة أمني'],\n logs:['كوّن خطاً زمنياً من السجلات التالية','استخرج محاولات الدخول غير المعتادة','حلّل سبب الإنذار الكاذب'],\n ioc:['صنّف مؤشرات الاختراق التالية','اكتب خطة Triage لهذه البصمات','أنشئ قائمة إجراءات استجابة'],\n ctf:['اشرح مفهوم buffer overflow بمثال تدريبي','كيف أفكر في تحدي Web CTF؟','اشرح قراءة PCAP داخل مختبر'],\n report:['أنشئ تقرير ثغرات من النتائج','اكتب تقرير حادث مختصر','رتّب النتائج حسب الأولوية']\n};\nlet active='assistant';let history={};let key=sessionStorage.getItem('wormstar-access')||'';\nconst el=id=>document.getElementById(id);\nfunction showLab(ok){el('auth').style.display=ok?'none':'block';el('lab').style.display=ok?'block':'none';el('logout').style.display=ok?'block':'none';if(ok){render();}else{el('studio').style.display='none';}}\nasync function verify(input){const r=await fetch('/api/auth',{method:'POST',headers:{Authorization:'Bearer '+input}});return r.ok;}\nel('loginForm').addEventListener('submit',async e=>{e.preventDefault();const input=el('token').value.trim();el('authStatus').textContent='جارٍ التحقق...';\n try{if(await verify(input)){key=input;sessionStorage.setItem('wormstar-access',input);el('authStatus').textContent='';showLab(true);}else el('authStatus').textContent='مفتاح غير صحيح أو لم يتم إعداد الحساب بعد.';}\n catch{el('authStatus').textContent='تعذر الوصول للخدمة.';}});\nel('logout').onclick=()=>{key='';sessionStorage.removeItem('wormstar-access');showLab(false);el('token').value='';};\nif(key){verify(key).then(ok=>{if(ok)showLab(true);else{sessionStorage.removeItem('wormstar-access');key='';}}).catch(()=>{});}\nfunction render(){\n el('modeKey').textContent=active.toUpperCase();el('consoleMode').textContent=active;el('modeTitle').textContent=titles[active][0];el('modeDesc').textContent=titles[active][1];\n document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===active));\n const wrap=el('messages');wrap.textContent='';let items=history[active]||[];\n if(!items.length){const home=document.createElement('div');home.className='welcome';const icon=document.createElement('div');icon.className='symbol';icon.textContent='◇';home.appendChild(icon);\n const h=document.createElement('h2');h.textContent='كيف أقدر أساعدك اليوم؟';home.appendChild(h);const p=document.createElement('p');p.textContent='اختر اقتراحاً أو ألصق محتوى لبدء التحليل السحابي.';home.appendChild(p);\n const grid=document.createElement('div');grid.className='prompts';for(const sample of examples[active]){const b=document.createElement('button');b.type='button';b.textContent=sample;b.onclick=()=>{el('prompt').value=sample;el('prompt').focus();el('counter').textContent=sample.length;};grid.appendChild(b);}home.appendChild(grid);wrap.appendChild(home);}\n items.forEach(m=>{\n const card=document.createElement('div');\n card.className='message '+(m.role==='assistant'?'ai':'user');\n const who=document.createElement('div');who.className='who';\n who.textContent=m.role==='assistant'?'Wormstar AI':'أنت';\n const bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=m.content;\n card.append(who,bubble);\n if(m.role==='assistant'){\n   if(Array.isArray(m.memoryUsed)&&m.memoryUsed.length){\n     const sources=document.createElement('div');sources.className='ws-memory-sources';\n     sources.textContent='مراجع من الذاكرة: '+m.memoryUsed.map(x=>x.title).join('، ');\n     card.appendChild(sources);\n   }\n   const actions=document.createElement('div');actions.className='ws-ai-actions';\n   const save=document.createElement('button');save.type='button';save.textContent='＋ حفظ الإجابة في الذاكرة';save.className='ghost';\n   save.onclick=()=>{\n     el('noteTitle').value='إجابة '+titles[active][0];\n     el('noteBody').value=m.content.slice(0,60000);\n     el('noteKind').value='note';showStudio(true);\n   };\n   const correct=document.createElement('button');correct.type='button';correct.textContent='✎ تعليم الذكاء من تصحيح';correct.className='ghost';\n   correct.onclick=()=>{\n     el('noteTitle').value='تصحيح إجابة '+titles[active][0];\n     el('noteBody').value='الإجابة السابقة:\\n'+m.content.slice(0,30000)+'\\n\\nالتصحيح الذي يجب الالتزام به مستقبلاً:\\n';\n     el('noteKind').value='correction';showStudio(true);\n   };\n   actions.append(save,correct);card.appendChild(actions);\n }\n wrap.appendChild(card);\n});\nwrap.scrollTop=wrap.scrollHeight;\n}\ndocument.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{active=button.dataset.mode;el('status').textContent='';el('prompt').value='';el('counter').textContent='0';el('indicators').textContent='';showStudio(false);render();});\nel('policyDetails').onclick=async()=>{\n try{\n  const r=await fetch('/api/lab/policy',{headers:{'Authorization':'Bearer '+key}});\n  const data=await r.json();\n  if(!r.ok)throw Error(data.error||'Error loading policy');\n  const allowed=Object.entries(data.capabilities).filter(([name,v])=>v).map(([name])=>name).join(' ، ');\n  const blocked=Object.entries(data.capabilities).filter(([name,v])=>!v).map(([name])=>name).join(' ، ');\n  alert('Wormstar AI Lab v'+data.version+'\\nالمسموح: '+allowed+'\\nالمحظور على الخادم: '+blocked+'\\nالتغييرات التقنية تتطلب تعديل ملف permissions.json وإعادة النشر.');\n }catch(e){el('policyBanner').textContent='تعذر تحميل السياسة: '+e.message;}\n};\n\nel('clear').onclick=()=>{history[active]=[];render();};\nel('export').onclick=()=>{const list=history[active]||[];if(!list.length)return;let s='# Wormstar AI Lab - '+titles[active][0]+'\\n\\n';list.forEach(m=>{s+='## '+(m.role==='assistant'?'التحليل':'السؤال')+'\\n\\n'+m.content+'\\n\\n';});const a=document.createElement('a');const u=URL.createObjectURL(new Blob([s],{type:'text/markdown;charset=utf-8'}));a.href=u;a.download='wormstar-report.md';a.click();URL.revokeObjectURL(u);};\nel('prompt').addEventListener('input',()=>{\n  const v=el('prompt').value;\n  el('counter').textContent=v.length;\n  el('indicators').textContent='';\n  if(active==='ioc'){\n    const parts=v.replaceAll(String.fromCharCode(10),' ').replaceAll(String.fromCharCode(9),' ').split(' ');\n    const indicators=[...new Set(parts.filter(p=>{\n      const bytes=p.split('.');\n      const ip=bytes.length===4 && bytes.every(x=>x!=='' && Number.isInteger(Number(x)) && Number(x)>=0 && Number(x)<=255);\n      const hash=p.length===64 && Array.from(p).every(c=>'0123456789abcdefABCDEF'.includes(c));\n      return p.startsWith('https://') || p.startsWith('http://') || ip || hash;\n    }))].slice(0,10);\n    if(indicators.length)el('indicators').textContent='مؤشرات في النص: '+indicators.join('   |   ');\n  }\n});\nel('form').onsubmit=async(e)=>{e.preventDefault();const text=el('prompt').value.trim();if(!text)return;let arr=history[active]||[];const prev=arr.slice(-6);arr.push({role:'user',content:text});history[active]=arr;el('prompt').value='';el('counter').textContent='0';el('status').textContent='جارٍ التحليل...';el('submit').disabled=true;render();\ntry{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({mode:active,message:text,history:prev})});const data=await r.json();if(!r.ok)throw Error(data.error||'عطل في الطلب');arr.push({role:'assistant',content:data.answer,memoryUsed:Array.isArray(data.memoryUsed)?data.memoryUsed:[]});el('status').textContent='';render();}\ncatch(err){el('status').textContent='فشل التحليل: '+(err.message||'خطأ غير معروف');el('prompt').value=text;}finally{el('submit').disabled=false;}};\n\nconst studioApi=async(path,method='GET',data)=>{\n  const res=await fetch(path,{method,headers:{'Authorization':'Bearer '+key,...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)})});\n  let jsonData;try{jsonData=await res.json();}catch{throw Error('تعذر قراءة ردّ الخادم');}\n  if(!res.ok)throw Error(jsonData.error||'تعذر تنفيذ الطلب');\n  return jsonData;\n};\nlet library=[];let openedId='';\nasync function loadStudio(){\n  if(!key)return;\n  try{\n    const [profile,listing,policyData]=await Promise.all([studioApi('/api/studio/profile'),studioApi('/api/studio/knowledge'),studioApi('/api/studio/policy')]);\n    showPolicy(policyData.policy);\n    el('aiName').value=profile.name||'Wormstar';\n    el('aiInstructions').value=profile.instructions||'';\n    el('aiLimits').value=profile.constraints||'';\n    library=listing.items||[];\n    el('memoryCount').textContent=library.length+' مرجع';\n    renderLibrary();\n  }catch(e){el('knowledgeStatus').textContent='تعذر تحميل الذاكرة: '+e.message;}\n}\nfunction showStudio(isStudio){\n  el('lab').style.display=isStudio?'none':'block';\n  el('studio').style.display=isStudio?'block':'none';\n  el('studioTab').classList.toggle('active',isStudio);\n  if(isStudio)void loadStudio();\n}\nel('studioTab').onclick=()=>{if(key)showStudio(true);};\nel('backToChat').onclick=()=>showStudio(false);\nel('studioRefresh').onclick=()=>void loadStudio();\nel('saveProfile').onclick=async()=>{\n  const elStatus=el('profileStatus');elStatus.textContent='جارٍ الحفظ...';\n  try{const profile={name:el('aiName').value,instructions:el('aiInstructions').value,constraints:el('aiLimits').value};await studioApi('/api/studio/profile','PUT',profile);await sbTryMirrorProfile(profile);elStatus.textContent='✓ حُفظت التعليمات وستُطبّق على الرسائل القادمة.';}\n  catch(e){elStatus.textContent='تعذر حفظ التعليمات: '+e.message;}\n};\nasync function addKnowledge(title,content,kind){\n  const saved=await studioApi('/api/studio/knowledge','POST',{title,content,kind});\n  await sbTryMirrorItem({id:saved.id,title,content,kind});\n  return saved;\n}\nel('saveNote').onclick=async()=>{\n  const title=el('noteTitle').value.trim(), content=el('noteBody').value.trim();\n  const status=el('knowledgeStatus');status.textContent='جارٍ إضافة المرجع...';\n  try{if(!title||!content)throw Error('أدخل عنواناً ومحتوى للمرجع');await addKnowledge(title,content,el('noteKind').value);el('noteTitle').value='';el('noteBody').value='';status.textContent='✓ أُضيف المرجع إلى الذاكرة الدائمة.';await loadStudio();}\n  catch(e){status.textContent='تعذرت الإضافة: '+e.message;}\n};\nel('importFiles').onclick=async()=>{\n  const status=el('knowledgeStatus'), files=Array.from(el('uploadFiles').files||[]);\n  if(!files.length){status.textContent='اختر ملفاً نصياً أو كوداً أولاً.';return;}\n  let ok=0;const errors=[];status.textContent='جارٍ حفظ '+files.length+' ملف...';\n  for(const file of files){\n    try{\n      if(file.size>80000)throw Error('حجم الملف أكبر من 80KB');\n      const content=await file.text();\n      if(!content.trim())throw Error('ملف فارغ');\n      if(content.includes('\\uFFFD'))throw Error('صيغة الملف ليست نص UTF-8');\n      await addKnowledge(file.name,content,'file');ok++;\n    }catch(e){errors.push(file.name+': '+e.message);}\n  }\n  status.textContent='✓ تم حفظ '+ok+' ملف.'+(errors.length?'\\n'+errors.join('\\n'):'');\n  el('uploadFiles').value='';\n  await loadStudio();\n};\nlet libraryKind='all';\nfunction renderLibrary(){\n  const list=el('memoryList');list.textContent='';\n  const q=el('memorySearch').value.trim().toLowerCase();\n  const rows=library.filter(item=>(libraryKind==='all'||item.kind===libraryKind)&&(item.title+' '+item.preview).toLowerCase().includes(q));\n  el('libraryVisibleCount').textContent='عرض '+rows.length+' من أصل '+library.length+' مرجع';\n  document.querySelectorAll('[data-library-kind]').forEach(b=>b.classList.toggle('active',b.dataset.libraryKind===libraryKind));\n  if(!rows.length){const p=document.createElement('p');p.textContent='لا توجد مراجع مطابقة.';list.appendChild(p);}\n  rows.forEach(item=>{\n    const row=document.createElement('div');row.className='ws-note-row';\n    const summary=document.createElement('div');\n    const title=document.createElement('strong');title.textContent=item.title;\n    const sub=document.createElement('small');sub.textContent=item.kind+' • '+item.updated_at+' • '+(item.preview||'').slice(0,90);\n    summary.append(title,sub);const actions=document.createElement('div');actions.className='ws-note-actions';\n    const edit=document.createElement('button');edit.textContent='فتح / تعديل';edit.onclick=()=>void openMemory(item.id);\n    const del=document.createElement('button');del.textContent='حذف';del.onclick=()=>void removeMemory(item.id,item.title);\n    actions.append(edit,del);row.append(summary,actions);list.appendChild(row);\n  });\n}\nel('memorySearch').oninput=renderLibrary;\ndocument.querySelectorAll('[data-library-kind]').forEach(b=>b.onclick=()=>{libraryKind=b.dataset.libraryKind;renderLibrary();});\nconst libraryTemplates={\n architecture:{title:'هندسة مشروع برمجي — المتطلبات والتنفيذ',kind:'note',body:'المهمة:\\nلغة البرمجة والإطار:\\nالبيئة والنطاق:\\nالمتطلبات الوظيفية:\\nمدخلات ومخرجات API:\\nالأذونات والبيانات الحساسة:\\nالاختبارات المطلوبة:\\nمعايير نجاح الإصدار:\\n'},\n security:{title:'مراجعة أمنية مصرح بها — أدلة وتوصيات',kind:'note',body:'الأصل والنطاق المصرح:\\nالتهديد المحتمل:\\nالدليل/السجل:\\nشدة الخطر وسببها:\\nخطوات تحقق دفاعية:\\nالإصلاح المقترح:\\nاختبار منع عودة المشكلة:\\n'},\n correction:{title:'تصحيح معرفي — تعليم Wormstar NEO',kind:'correction',body:'السؤال الأصلي:\\nالإجابة السابقة:\\nالمعلومة أو الكود الصحيح مع الدليل:\\nالقاعدة المستفادة لتطبيقها على الأسئلة المشابهة:\\nحالات استثناء:\\n'},\n incident:{title:'تحليل حادث — سجل زمني ومؤشرات',kind:'note',body:'ملخص الحادث:\\nمصدر السجلات وفترة زمنية:\\nالأحداث المؤكدة:\\nمؤشرات الاختراق ومستوى الثقة:\\nتسلسل الوقائع:\\nالاحتواء والإصلاح:\\nالأسئلة المفتوحة والتوصيات:\\n'}\n};\nel('noteTemplate').onchange=()=>{\n const t=libraryTemplates[el('noteTemplate').value];\n if(!t)return;\n if((el('noteTitle').value.trim()||el('noteBody').value.trim())&&!confirm('استبدال النص الذي كتبته في نموذج المعرفة بالقالب المختار؟')){el('noteTemplate').value='';return;}\n el('noteTitle').value=t.title;el('noteKind').value=t.kind;el('noteBody').value=t.body;el('noteTemplate').value='';\n};\nasync function openMemory(id){\n  try{const item=await studioApi('/api/studio/knowledge/'+encodeURIComponent(id));openedId=id;el('editTitle').value=item.title;el('editContent').value=item.content;el('memoryEditor').classList.remove('hidden');el('memoryEditor').scrollIntoView({behavior:'smooth',block:'nearest'});}\n  catch(e){el('knowledgeStatus').textContent=e.message;}\n}\nel('cancelMemory').onclick=()=>{openedId='';el('memoryEditor').classList.add('hidden');};\nel('updateMemory').onclick=async()=>{\n  if(!openedId)return;\n  try{const title=el('editTitle').value,content=el('editContent').value;const original=library.find(x=>x.id===openedId);await studioApi('/api/studio/knowledge/'+encodeURIComponent(openedId),'PUT',{title,content});await sbTryMirrorItem({id:openedId,title,content,kind:original?.kind||'note'});el('memoryEditor').classList.add('hidden');openedId='';el('knowledgeStatus').textContent='✓ تم تحديث المرجع.';await loadStudio();}\n  catch(e){el('knowledgeStatus').textContent=e.message;}\n};\nasync function removeMemory(id,title){\n  if(!confirm('حذف المرجع نهائياً؟\\n'+title))return;\n  try{await studioApi('/api/studio/knowledge/'+encodeURIComponent(id),'DELETE');if(sbSession){try{await sbDeleteItem(id);sbNote('✓ حُذف المرجع من النسختين.');}catch(error){sbNote('حُذف من D1، لكن تعذر حذفه من Supabase: '+error.message);}}el('knowledgeStatus').textContent='تم حذف المرجع.';await loadStudio();}\n  catch(e){el('knowledgeStatus').textContent=e.message;}\n}\nel('studioExport').onclick=async()=>{\n  try{\n    const result=await studioApi('/api/studio/export');\n    const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json;charset=utf-8'});\n    const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='wormstar-knowledge-backup.json';a.click();URL.revokeObjectURL(url);\n    el('knowledgeStatus').textContent='✓ تم تجهيز النسخة الاحتياطية.';\n  }catch(e){el('knowledgeStatus').textContent=e.message;}\n};\n\nconst SB_URL='https://xwigjsrbalbjwwjkxyma.supabase.co';\nconst SB_PUBLIC='sb_publishable_RlV4mTHoLYnGwtPrvrJgJg_9GDmQnKl';\nconst SB_SESSION_KEY='wormstar-sb-session',SB_REMEMBER_KEY='wormstar-sb-remember';\nlet sbSession=null,sbRememberChoice=true;\ntry{\n sbRememberChoice=localStorage.getItem(SB_REMEMBER_KEY)!=='false';\n const stored=localStorage.getItem(SB_SESSION_KEY)||sessionStorage.getItem(SB_SESSION_KEY);\n if(stored)sbSession=JSON.parse(stored);\n if(!sbSession?.access_token||!sbSession?.refresh_token||!sbSession?.user?.id)sbSession=null;\n}catch{sbSession=null;}\nfunction sbPersistSession(){\n if(!sbSession?.access_token||!sbSession?.refresh_token)return;\n if(sbRememberChoice){localStorage.setItem(SB_SESSION_KEY,JSON.stringify(sbSession));sessionStorage.removeItem(SB_SESSION_KEY);}\n else{sessionStorage.setItem(SB_SESSION_KEY,JSON.stringify(sbSession));localStorage.removeItem(SB_SESSION_KEY);}\n localStorage.setItem(SB_REMEMBER_KEY,String(sbRememberChoice));\n}\nfunction sbForgetSession(){sbSession=null;localStorage.removeItem(SB_SESSION_KEY);sessionStorage.removeItem(SB_SESSION_KEY);}\n\nfunction sbNote(message){el('sbStatus').textContent=message;}\nfunction sbUI(){\n const yes=!!(sbSession&&sbSession.access_token&&sbSession.user?.id);\n el('sbSignedIn').classList.toggle('hidden',!yes);\n el('sbSignedOut').classList.toggle('hidden',yes);\n if(yes)el('sbCurrentUser').textContent=sbSession.user.email||sbSession.user.id;\n el('sbCloudBadge').textContent=yes?'جلسة متصلة':'غير متصل';\n el('sbCloudBadge').classList.toggle('connected',yes);\n if(!yes){\n  for(const id of ['sbCloudItems','sbCloudTraining','sbCloudVersions','sbCloudProfileState'])el(id).textContent='—';\n  el('sbHistory').textContent='';\n  const p=document.createElement('p');p.textContent='سجّل الدخول لعرض عمليات النسخ والاستعادة.';el('sbHistory').appendChild(p);\n  el('sbHistoryLabel').textContent='لم يرتبط أي حساب بعد';el('sbLastChecked').textContent='يلزم ربط حسابك';\n }\n}\nasync function sbAuthRequest(path,payload){\n const res=await fetch(SB_URL+'/auth/v1/'+path,{method:'POST',headers:{'apikey':SB_PUBLIC,'Content-Type':'application/json'},body:JSON.stringify(payload)});\n let data;try{data=await res.json();}catch{throw Error('Supabase authentication returned invalid JSON');}\n if(!res.ok)throw Error(data.msg||data.error_description||data.message||data.error||'Supabase authentication failed');\n return data;\n}\nlet sbRefreshPromise=null;\nasync function sbRefresh(){\n if(sbRefreshPromise)return sbRefreshPromise;\n if(!sbSession?.refresh_token)throw Error('Supabase session expired: sign in again');\n sbRefreshPromise=(async()=>{\n  const renewed=await sbAuthRequest('token?grant_type=refresh_token',{refresh_token:sbSession.refresh_token});\n  if(!renewed.access_token||!renewed.refresh_token||!renewed.user?.id)throw Error('Unable to refresh Supabase session');\n  sbSession=renewed;sbPersistSession();\n  return renewed;\n })();\n try{return await sbRefreshPromise;}\n finally{sbRefreshPromise=null;}\n}\nasync function sbRest(path,method='GET',data,once=false){\n if(!sbSession?.access_token)throw Error('اربط حساب Supabase أولاً');\n const headers={'apikey':SB_PUBLIC,'Authorization':'Bearer '+sbSession.access_token};\n if(data!==undefined)headers['Content-Type']='application/json';\n if(method==='POST')headers['Prefer']='resolution=merge-duplicates,return=minimal';\n const res=await fetch(SB_URL+'/rest/v1/'+path,{method,headers,...(data===undefined?{}:{body:JSON.stringify(data)})});\n if(res.status===401&&!once){await sbRefresh();return sbRest(path,method,data,true);}\n if(!res.ok){\n   let issue;try{issue=await res.json();}catch{issue={};}\n   throw Error(issue.message||issue.details||('Supabase HTTP '+res.status));\n }\n if(res.status===204)return null;\n const t=await res.text();return t?JSON.parse(t):null;\n}\nasync function sbStoreProfile(profile){\n const row={owner_id:sbSession.user.id,name:profile.name||'Wormstar',instructions:profile.instructions||'',constraints:profile.constraints||''};\n return sbRest('wormstar_ai_profiles?on_conflict=owner_id','POST',row);\n}\nasync function sbStoreItem(item){\n const row={id:item.id,owner_id:sbSession.user.id,kind:['file','note','correction','research','code'].includes(item.kind)?item.kind:'note',title:item.title,content:item.content};\n await sbRest('wormstar_memory_items?on_conflict=id','POST',row);\n if(row.kind==='correction'){\n   await sbRest('wormstar_training_events?on_conflict=owner_id,source_item_id','POST',{\n     owner_id:row.owner_id,source_item_id:row.id,kind:'correction',subject:row.title,content:row.content\n   });\n }\n}\nasync function sbDeleteItem(id){\n await sbRest('wormstar_memory_items?id=eq.'+encodeURIComponent(id),'DELETE');\n}\nasync function sbGetMemory(){\n return sbRest('wormstar_memory_items?select=id,title,kind,content,updated_at&order=updated_at.desc&limit=120');\n}\nasync function sbGetProfile(){\n const rows=await sbRest('wormstar_ai_profiles?select=name,instructions,constraints&limit=1');\n return Array.isArray(rows)&&rows.length?rows[0]:null;\n}\n\nasync function sbRecordEvent(action,count=0,details={}){\n if(!sbSession?.user?.id)return;\n try{await sbRest('wormstar_sync_events','POST',{owner_id:sbSession.user.id,action,outcome:'success',item_count:count,details});}\n catch(e){sbNote('تم حفظ البيانات، لكن سجل العملية لم يُحفظ: '+e.message);}\n}\nfunction sbRenderHistory(events){\n const list=el('sbHistory');list.textContent='';\n if(!events.length){const p=document.createElement('p');p.textContent='لا توجد عمليات مزامنة مكتملة بعد.';list.appendChild(p);return;}\n const titles={backup:'نسخ المعلومات',restore_memory:'استعادة المراجع',restore_policy:'استعادة سياسة الذكاء'};\n for(const event of events){\n  const row=document.createElement('div');row.className='sb-history-row';\n  const mark=document.createElement('span');mark.className='sb-event-mark';mark.textContent=event.action==='backup'?'↑':'↓';\n  const body=document.createElement('div');const name=document.createElement('b');name.textContent=titles[event.action]||'مزامنة';\n  const when=document.createElement('small');when.textContent=new Date(event.created_at).toLocaleString('ar-IQ');\n  body.append(name,when);\n  const count=document.createElement('span');count.className='sb-event-success';count.textContent=event.item_count+' مرجع';\n  row.append(mark,body,count);list.appendChild(row);\n }\n}\nasync function sbRefreshOverview(){\n if(!sbSession?.access_token){sbUI();return;}\n const userId=sbSession.user?.id;\n try{\n  const [items,training,versions,profiles,policies,events]=await Promise.all([\n   sbRest('wormstar_memory_items?select=id&limit=121'),\n   sbRest('wormstar_training_events?select=id&limit=121'),\n   sbRest('wormstar_memory_versions?select=id&limit=121'),\n   sbRest('wormstar_ai_profiles?select=owner_id&limit=1'),\n   sbRest('wormstar_owner_policies?select=owner_id&limit=1'),\n   sbRest('wormstar_sync_events?select=action,outcome,item_count,created_at&order=created_at.desc&limit=6')\n  ]);\n  if(userId!==sbSession?.user?.id)return;\n  el('sbCloudItems').textContent=items.length>=121?'120+':String(items.length);\n  el('sbCloudTraining').textContent=training.length>=121?'120+':String(training.length);\n  el('sbCloudVersions').textContent=versions.length>=121?'120+':String(versions.length);\n  el('sbCloudProfileState').textContent=String(Number(profiles.length>0)+Number(policies.length>0))+'/2';\n  el('sbHistoryLabel').textContent=events.length+' عملية مسجّلة';\n  el('sbLastChecked').textContent='تحقّق: '+new Date().toLocaleTimeString('ar-IQ',{hour:'2-digit',minute:'2-digit'});\n  sbRenderHistory(events);\n  return true;\n }catch(e){sbNote('تعذّر قراءة ملخص الحساب: '+e.message);return false;}\n}\n\nasync function sbVerifyAndLockAccount(session){\n if(!session?.access_token||!session?.user?.id)throw Error('Supabase login is incomplete');\n const prior=await studioApi('/api/studio/supabase-owner');\n if(!prior.bound&&!confirm('هذا أول ربط لمالك ذاكرة Wormstar. سيتم تثبيت حساب Supabase الذي سجلت به لهذا المختبر، ولن يُسمح بحساب مختلف قبل نقل ملكية إداري موثّق. هل تؤكد أن هذا هو حسابك الصحيح؟'))throw Error('أُلغيت عملية ربط المالك. لم تُحفظ أي معلومات حساب جديدة.');\n const verified=await studioApi('/api/studio/supabase-owner','POST',{access_token:session.access_token});\n if(!verified.verified||verified.owner_id!==session.user.id)throw Error('This Supabase account does not match the verified Wormstar memory owner');\n if(el('sbOwnerLockStatus'))el('sbOwnerLockStatus').textContent='⛨ ربط آمن: تم التحقق من مالك ذاكرة Wormstar · '+(verified.email||'حساب محمي');\n return verified;\n}\n\nasync function sbCheckSession(){\n if(!sbSession?.access_token)return;\n try{\n  let response=await fetch(SB_URL+'/auth/v1/user',{headers:{'apikey':SB_PUBLIC,'Authorization':'Bearer '+sbSession.access_token}});\n  if(response.status===401){\n   await sbRefresh();\n   response=await fetch(SB_URL+'/auth/v1/user',{headers:{'apikey':SB_PUBLIC,'Authorization':'Bearer '+sbSession.access_token}});\n  }\n  if(!response.ok)throw Error('انتهت صلاحية جلسة Supabase، أعد تسجيل الدخول');\n  const user=await response.json();if(!user.id)throw Error('تعذّر التحقق من المستخدم');\n  await sbVerifyAndLockAccount(sbSession);\n  sbSession.user={...sbSession.user,id:user.id,email:user.email};\n  sbPersistSession();sbUI();\n  await sbRefreshOverview();\n }catch(e){sbForgetSession();sbUI();sbNote(e.message);}\n}\n\nasync function sbStorePolicy(policy){\n return sbRest('wormstar_owner_policies?on_conflict=owner_id','POST',{\n  owner_id:sbSession.user.id,policy_json:policy,updated_at:new Date().toISOString()\n });\n}\nasync function sbGetPolicy(){\n const rows=await sbRest('wormstar_owner_policies?select=policy_json,updated_at&limit=1');\n return Array.isArray(rows)&&rows.length?rows[0].policy_json:null;\n}\nasync function sbTryMirrorPolicy(policy){\n if(!sbSession)return;\n try{await sbStorePolicy(policy);sbNote('✓ قيود التشغيل محفوظة في D1 وSupabase');}\n catch(e){sbNote('القيود مطبّقة في D1، لكن فشل نسخها إلى Supabase: '+e.message);}\n}\nasync function sbTryMirrorItem(item){\n if(!sbSession)return;\n try{await sbStoreItem(item);sbNote('✓ آخر تعديل محفوظ على Supabase');}\n catch(e){sbNote('حُفظ على Cloudflare D1، لكن فشلت مزامنة Supabase: '+e.message);}\n}\nasync function sbTryMirrorProfile(profile){\n if(!sbSession)return;\n try{await sbStoreProfile(profile);sbNote('✓ إعدادات الشخصية محفوظة في Supabase');}\n catch(e){sbNote('حُفظت إعداداتك في D1، لكن فشلت مزامنة Supabase: '+e.message);}\n}\nel('sbLogin').onclick=async()=>{\n const email=el('sbEmail').value.trim(),password=el('sbPassword').value;\n if(!email||!password){sbNote('أدخل البريد وكلمة المرور');return;}\n sbNote('جارٍ الاتصال بحساب Supabase...');\n try{\n   const data=await sbAuthRequest('token?grant_type=password',{email,password});\n   if(!data.access_token||!data.user?.id)throw Error('لم يتم إنشاء جلسة صالحة');\n   sbRememberChoice=el('sbRemember').checked;\n   await sbVerifyAndLockAccount(data);\n   sbSession=data;sbPersistSession();\n   el('sbPassword').value='';\n   const saved=await sbGetMemory();\n   sbUI();\n   sbNote('✓ تم ربط الحساب. توجد '+saved.length+' مراجع في النسخة السحابية.');\n   await sbRefreshOverview();\n }catch(e){\n   sbNote('تعذر الربط: '+e.message);\n }\n};\n\nel('sbSignUp').onclick=async()=>{\n const email=el('sbEmail').value.trim(),password=el('sbPassword').value;\n if(!email||password.length<8){sbNote('أدخل بريدك وكلمة مرور لا تقل عن 8 أحرف');return;}\n sbNote('جارٍ إنشاء حساب Supabase...');\n try{\n  const session=await sbAuthRequest('signup',{email,password});\n  el('sbPassword').value='';\n  if(session.access_token&&session.user?.id){\n   sbRememberChoice=el('sbRemember').checked;\n   await sbVerifyAndLockAccount(session);\n   sbSession=session;sbPersistSession();sbUI();\n   sbNote('✓ الحساب جاهز. يمكنك الآن نسخ الذاكرة إلى Supabase.');await sbRefreshOverview();\n  }else{\n   sbNote('طلب إنشاء الحساب أُرسل. إذا كان التأكيد بالبريد مفعّلاً، أكّد البريد ثم سجّل الدخول من هذا الاستوديو.');\n  }\n }catch(e){sbNote('تعذر إنشاء الحساب: '+e.message+'. قد يكون تسجيل الحسابات الجديدة مقفلاً في إعدادات Supabase.');}\n};\n\nel('sbLogout').onclick=async()=>{\n const token=sbSession?.access_token;\n sbForgetSession();sbUI();sbNote('تم فصل جلسة Supabase عن هذا الجهاز. ارتباط مالك الذاكرة على الخادم باقٍ لمنع اختلاط الحسابات.');\n if(token){try{await fetch(SB_URL+'/auth/v1/logout',{method:'POST',headers:{apikey:SB_PUBLIC,Authorization:'Bearer '+token}});}catch{}}\n};\nel('sbRemember').checked=sbRememberChoice;\nel('sbRemember').onchange=()=>{sbRememberChoice=el('sbRemember').checked;localStorage.setItem(SB_REMEMBER_KEY,String(sbRememberChoice));if(sbSession)sbPersistSession();};\nel('sbImportStarter').onclick=async()=>{\n if(!sbSession){sbNote('سجّل الدخول إلى حساب Supabase أولاً.');return;}\n if(!confirm('استيراد المراجع التأسيسية الناقصة من Supabase إلى D1 دون تغيير الملفات الموجودة؟'))return;\n sbNote('أفحص المراجع الموجودة وأستورد الناقصة...');\n try{\n  const rows=await sbRest('wormstar_starter_library?select=slug,title,content,kind&order=slug.asc&limit=60');\n  const current=await studioApi('/api/studio/knowledge');\n  const known=new Set((current.items||[]).map(x=>x.title));\n  let added=0,skipped=0;\n  for(const item of rows){\n   if(known.has(item.title)){skipped++;continue;}\n   const addedItem=await studioApi('/api/studio/knowledge','POST',{title:item.title,content:item.content,kind:item.kind||'note'});\n   await sbTryMirrorItem({id:addedItem.id,title:item.title,content:item.content,kind:item.kind||'note'});\n   known.add(item.title);added++;\n  }\n  await loadStudio();sbNote('✓ تمت إضافة '+added+' مرجعاً، وتخطي '+skipped+' مرجعاً موجوداً مسبقاً.');\n }catch(e){sbNote('تعذر استكمال الاستيراد: '+e.message);}\n};\nel('sbRefreshStats').onclick=async()=>{sbNote('جارٍ تحديث ملخص Supabase...');if(await sbRefreshOverview())sbNote('✓ اكتمل تحديث الإحصائيات وسجل المزامنة.');};\nel('sbResetPassword').onclick=async()=>{\n const email=el('sbEmail').value.trim();\n if(!email){sbNote('أدخل البريد الإلكتروني أولاً.');return;}\n try{await sbAuthRequest('recover',{email});sbNote('إذا كان الحساب مسجلاً فستصلك رسالة استعادة كلمة المرور على البريد الإلكتروني.');}\n catch(e){sbNote('تعذر إرسال رسالة الاستعادة: '+e.message);}\n};\nel('sbBackupNow').onclick=async()=>{\n sbNote('جارٍ فحص المراجع ومزامنتها...');\n try{\n   const [local,remote]=await Promise.all([studioApi('/api/studio/export'),sbGetMemory()]);\n   await sbStoreProfile(local.profile);\n   await sbStorePolicy(local.policy);\n   const known=new Map(remote.map(x=>[x.id,x]));\n   let changed=0;\n   for(const item of local.knowledge||[]){\n     const previous=known.get(item.id);\n     if(previous&&previous.title===item.title&&previous.content===item.content&&previous.kind===item.kind)continue;\n     await sbStoreItem(item);changed++;\n   }\n   await sbRecordEvent('backup',changed,{total_local:(local.knowledge||[]).length});\n   sbNote('✓ تم نسخ الشخصية والسياسة ومراجعة '+(local.knowledge||[]).length+' مرجعاً؛ الجديد أو المحدث: '+changed+'.');\n   await sbRefreshOverview();\n }catch(e){sbNote('فشلت المزامنة أو اكتملت جزئياً: '+e.message+'. يمكنك المحاولة مجدداً.');}\n};\nel('sbRestoreNow').onclick=async()=>{\n if(!confirm('استعادة نسخة Supabase إلى Cloudflare D1؟ لن تُحذف المراجع المحلية الموجودة.'))return;\n sbNote('جارٍ استعادة المراجع...');\n try{\n   const [remote,profile]=await Promise.all([sbGetMemory(),sbGetProfile()]);\n   let added=0,skipped=0;\n   for(const item of remote){\n     const result=await studioApi('/api/studio/restore','POST',{item});\n     if(result.imported)added++;else skipped++;\n   }\n   if(profile&&confirm('هل تريد أيضاً استبدال تعليمات الشخصية الحالية بالنسخة المحفوظة في Supabase؟')){\n     await studioApi('/api/studio/profile','PUT',profile);\n   }\n   await loadStudio();\n   await sbRecordEvent('restore_memory',added,{already_present:skipped});\n   sbNote('✓ اكتملت الاستعادة: '+added+' مرجع تمت إضافته و'+skipped+' موجود مسبقاً.');\n   await sbRefreshOverview();\n }catch(e){sbNote('توقفت الاستعادة أو اكتملت جزئياً: '+e.message);}\n};\nel('sbRestorePolicy').onclick=async()=>{\n if(!sbSession){sbNote('اربط حساب Supabase أولاً');return;}\n if(!confirm('استعادة سياسة التشغيل من Supabase وتطبيقها على خادم Cloudflare؟ ستستبدل إعدادات القيود الحالية، لكن لا يمكنها تجاوز صلاحيات permissions.json.'))return;\n sbNote('جارٍ قراءة نسخة قيود التشغيل...');\n try{\n  const backup=await sbGetPolicy();\n  if(!backup){sbNote('لا توجد نسخة محفوظة لقيود التشغيل في Supabase. استخدم النسخ الاحتياطي أولاً.');return;}\n  const result=await studioApi('/api/studio/policy','PUT',backup);\n  showPolicy(result.policy);\n  await sbRecordEvent('restore_policy',0,{policy:true});\n  sbNote('✓ تمت استعادة قيود التشغيل وتطبيقها على Cloudflare D1.');\n  await sbRefreshOverview();\n }catch(e){sbNote('تعذرت استعادة السياسة: '+e.message);}\n};\nsbUI();\nif(sbSession)void sbCheckSession();\n\nel('importResearch').onclick=async()=>{\n const target=el('researchUrl').value.trim();\n if(!target){el('knowledgeStatus').textContent='أدخل رابط صفحة HTTPS';return;}\n el('knowledgeStatus').textContent='جارٍ جلب الصفحة عبر Firecrawl...';\n try{\n  const entry=await studioApi('/api/studio/import-web','POST',{url:target});\n  if(sbSession){\n   const full=await studioApi('/api/studio/knowledge/'+encodeURIComponent(entry.id));\n   await sbTryMirrorItem(full);\n  }\n  await loadStudio();\n  el('knowledgeStatus').textContent='✓ حُفظت الصفحة بعنوان: '+entry.title;\n }catch(e){el('knowledgeStatus').textContent='لم يتم استيراد الصفحة: '+e.message;}\n};\n\nfunction showPolicy(p){\n el('pMission').value=p.mission||'';\n el('pStyle').value=p.answer_style||'';\n el('pRequired').value=(p.required_terms||[]).join('\\n');\n el('pWorkflow').value=(p.workflow_steps||[]).join('\\n');\n el('pMaxInput').value=p.max_input_chars;el('pMaxTokens').value=p.max_output_tokens;\n el('pMemory').checked=!!p.memory_enabled;el('pWeb').checked=!!p.allow_web_import;el('pDelete').checked=!!p.allow_memory_delete;\n document.querySelectorAll('[data-policy-mode]').forEach(x=>{x.checked=p.allowed_modes.includes(x.dataset.policyMode);});\n}\nfunction policyDraft(){\n return {\n  version:1,mission:el('pMission').value.trim(),answer_style:el('pStyle').value.trim(),\n  allowed_modes:Array.from(document.querySelectorAll('[data-policy-mode]:checked')).map(x=>x.dataset.policyMode),\n  required_terms:el('pRequired').value.split('\\n').map(s=>s.trim()).filter(Boolean),\n  workflow_steps:el('pWorkflow').value.split('\\n').map(s=>s.trim()).filter(Boolean),\n  max_input_chars:Number(el('pMaxInput').value),max_output_tokens:Number(el('pMaxTokens').value),\n  memory_enabled:el('pMemory').checked,allow_web_import:el('pWeb').checked,\n  allow_memory_delete:el('pDelete').checked\n };\n}\nel('pSave').onclick=async()=>{\n el('pStatus').textContent='جارٍ حفظ السياسة على Cloudflare...';\n try{\n  const result=await studioApi('/api/studio/policy','PUT',policyDraft());\n  showPolicy(result.policy);\n  await sbTryMirrorPolicy(result.policy);\n  el('pStatus').textContent='✓ تم تطبيق القيود على الطلبات الجديدة في Cloudflare.';\n }catch(e){el('pStatus').textContent='فشل الحفظ: '+e.message;}\n};\nel('pReload').onclick=async()=>{\n try{const response=await studioApi('/api/studio/policy');showPolicy(response.policy);el('pStatus').textContent='✓ تمت استعادة آخر سياسة محفوظة.';}\n catch(e){el('pStatus').textContent='فشل التحميل: '+e.message;}\n};\nel('pTest').onclick=async()=>{\n el('pTestResult').textContent='جارٍ الاختبار دون استدعاء النموذج...';\n try{\n  const result=await studioApi('/api/studio/policy/evaluate','POST',{draft:policyDraft(),mode:el('pTestMode').value,message:el('pTestInput').value});\n  el('pTestResult').textContent=result.allowed?'✓ هذا الطلب مسموح ضمن السياسة':'⛔ مرفوض: '+result.reason;\n }catch(e){el('pTestResult').textContent='فشل الاختبار: '+e.message;}\n};\n\n})();\n</script>\n</body></html>";
